/** Normalize only the explicitly reviewed display adapter into its old semantic
 * carrier. Original fixtures/oracles stay unchanged, and inspect reads actual
 * native programs/banks before passing all choices to the independent oracle.
 */
import assert from 'node:assert/strict';import type {GeneratedBody} from '../../src/core/generators/definition';import type {Block} from '../../src/core/types';
import {legacy2018SpringPm9Figure as figure9,legacy2018SpringPm9Profiles as profiles9} from '../../src/core/generators/legacy-2018-spring-pm9';import {legacy2018SpringPm10Figure as figure10,legacy2018SpringPm10Profiles as profiles10} from '../../src/core/generators/legacy-2018-spring-pm10';
import {legacy2018CSummaryOracle} from './legacy-2018-pm-c-summary-oracle';import {legacy2018OrderPaymentOracle,orderPaymentAnswerIndices} from './legacy-2018-pm-order-payment-oracle';import paymentFacts from './legacy-2018-pm-order-payment-facts.json';
const text=(bs:Block[])=>bs.map(b=>b.type==='code'||b.type==='paragraph'?b.text:b.type==='table'?b.rows.map(r=>r.join(' | ')).join('\n'):'').join('\n');
export function reviewSpringPm9(body:GeneratedBody,values:number[]){const normalized=structuredClone(body);let banks=0;normalized.prompt=body.prompt.flatMap(block=>{if(block.type!=='diagram'||block.scene.kind!=='source_figure')return[block];const {profile,values:args}=block.scene,f=figure9(profile,args),index=profiles9.indexOf(profile as typeof profiles9[number]);assert.equal(block.caption,f.caption);assert.equal(block.alt,f.alt);if(index>=2)assert.deepEqual(args.slice(0,2),values,'source-local input binding');if(index===3){const ranges=[[0,4],[4,9],[9,15]],g=args[2];assert.deepEqual(f.kind==='bank'?f.items:[],body.choices.slice(...ranges[g] as [number,number]).map(text));banks++;return[];}if(index===2)return[{type:'code' as const,text:f.text,language:'c'}];if(index===4)return[{type:'paragraph' as const,text:f.text.replaceAll('［　］','［空欄］')}];if(index===5)return[{type:'table' as const,caption:f.caption,columns:['発生し得る事象','valueとvalueMaxの値の例'],rows:f.text.split('\n').map(s=>s.split(' | '))}];assert(f.kind==='old_figure');return[{...structuredClone(block),scene:{kind:'source_figure' as const,profile:f.oldProfile,values:[...args]}}];});assert.equal(banks,3);legacy2018CSummaryOracle(normalized,values);return normalized;}
export function reviewSpringPm10(body:GeneratedBody,values:number[]){
 const isFigure=(b:Block,suffix:string)=>b.type==='diagram'&&b.scene.kind==='source_figure'&&b.scene.profile.endsWith(suffix),table=body.prompt.findIndex(b=>isFigure(b,'-change-table')),note=body.prompt.findIndex(b=>b.type==='paragraph'&&b.text==='注1) プログラムを実行した日付が，YYYYMMDD形式でCR-DATE-Xに格納される。'),bank=(group:number)=>body.prompt.findIndex(b=>isFigure(b,'-bank')&&b.type==='diagram'&&b.scene.kind==='source_figure'&&b.scene.values[2]===group);
 assert(table>=0);assert.deepEqual([note,bank(3),bank(4)],[table+1,table+2,table+3],'SOURCE_NOTE_AND_BANK_ORDER');
 const normalized=structuredClone(body);let banks=0;normalized.prompt=body.prompt.flatMap(block=>{if(block.type!=='diagram'||block.scene.kind!=='source_figure')return[block];const {profile,values:args}=block.scene,f=figure10(profile,args),index=profiles10.indexOf(profile as typeof profiles10[number]);assert.equal(block.caption,f.caption);assert.equal(block.alt,f.alt);if(index===4){const ranges=[[0,4],[4,10],[10,14],[14,18],[18,22]],g=args[2];assert.deepEqual(f.kind==='bank'?f.items:[],body.choices.slice(...ranges[g] as [number,number]).map(text));banks++;return[];}if(index===3)return[{type:'code' as const,text:f.text,language:'cobol'}];if(index===5)return[{type:'paragraph' as const,text:f.text.replaceAll('［　］','［空欄］')}];assert(f.kind==='old_figure');return[{...structuredClone(block),scene:{kind:'source_figure' as const,profile:f.oldProfile,values:[...args]}}];});assert.equal(banks,5);
 // The live candidate uses the fixed original p2 image instead of duplicating its
 // prose. Its exact metadata/bytes are tested separately by the records packet.
 assert.deepEqual(body.contexts,[{title:'公式正誤表（問10）',presentation:'text_figure',blocks:[{type:'image',assetId:'asset-ipa-2018h30h-fe-pm-10-p2',caption:'平成30年度春期 付属資料 物理p.2'}]}]);
 normalized.contexts=[{title:'公式訂正の独立検算carrier',presentation:'text',blocks:[{type:'paragraph',text:'carrier only; actual p2 image is tested separately.'},{type:'paragraph',text:paymentFacts.erratum.correctedText}]}];legacy2018OrderPaymentOracle(normalized,values);orderPaymentAnswerIndices(normalized,values);return normalized;}
